def catalan(n: int) -> int:
    from math import comb
    return comb(2 * n, n) // (n + 1)

def lgv_2x2(n: int, d: int) -> int:
    from math import comb
    return comb(n + d, d) - comb(n, d)

def catalan_hankel(size, shift=0):
    from math import comb
    C = lambda n: comb(2*n, n) // (n+1)
    M = [[C(i+j+shift) for j in range(size)] for i in range(size)]
    def det(m):
        n = len(m)
        if n <= 1: return m[0][0] if n else 1
        return sum((-1)**j * m[0][j] * det([r[:j]+r[j+1:] for r in m[1:]]) for j in range(n))
    return det(M)

def q_binomial_poly(m, n):
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def qb(i, j):
        if i == 0 or j == 0: return (1,)
        a, b = list(qb(i-1, j)), [0]*j + list(qb(i, j-1))
        r = [0] * max(len(a), len(b))
        for k in range(len(a)): r[k] += a[k]
        for k in range(len(b)): r[k] += b[k]
        return tuple(r)
    return list(qb(m, n))
